mapper.select:
SELECT IN_TB.* FROM ( SELECT A.CUST_KOR_NAME , C.AUTO_RENEW_YN , C.CONTRACT_SEQ , C.CONTRACT_NM , C.CONTRACT_DT , C.MTAC_START_DT, C.MTAC_END_DT, (TO_NUMBER(TO_DATE(C.MTAC_END_DT, 'YYYYMMDD') - TO_DATE(TO_CHAR(SYSDATE , 'YYYYMMDD'), 'YYYYMMDD'))) MTAC_CALC , C.MON_OFF_AMT , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='CUST' AND P_CODE ='CD28' AND CODE = C.BILL_CODE) BILL_CODE , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='CUST' AND P_CODE ='CD29' AND CODE = C.MTAC_CODE) MTAC_CODE , ( SELECT SUM(UBO_AMT) - SUM(SU_AMT) FROM ( SELECT X.ERP_CODE, SUBSTR(SALE_DT,1,6) SALE_YM, SUM(NVL(UBO_AMT,0)) UBO_AMT, SUM(NVL(SU_AMT,0)) SU_AMT FROM ( SELECT DISTINCT ERP_CODE FROM CRM_CUST_MGT_HIST WHERE CRM_CODE = 'HOS204' ) X, (SELECT CUST_CD,SALE_DT,WON_AMT + VAT_AMT UBO_AMT ,COLL_WON_AMT SU_AMT FROM KYERP.TB_SD_RECEIVABLE_DTL WHERE ITEM_CD IN('C300000001','H000000110') ) Y WHERE X.ERP_CODE = Y.CUST_CD(+) AND Y.SALE_DT <= TO_CHAR(LAST_DAY( ADD_MONTHS(SYSDATE , -1)), 'YYYYMMDD') GROUP BY X.ERP_CODE,SUBSTR(SALE_DT,1,6) ORDER BY 1,2 ASC ) WHERE ERP_CODE = A.ERP_CODE ) RECEIVE_AMT ,
(SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='CUST' AND P_CODE ='CD36' AND CODE = C.BUY_BUSI_NAME) BUY_BUSI_NAME , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='CUST' AND P_CODE ='CD37' AND CODE = C.SERVICE_PERIOD) SERVICE_PERIOD , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='CUST' AND P_CODE ='CD38' AND CODE = C.SERVICE_METHOD) SERVICE_METHOD ,
C.BUY_COST , A.SEQ , A.CRM_CODE
FROM CRM_CUST_MGT A
INNER JOIN CRM_CUST_MAINTENANCE_HIST C ON A.SEQ = C.SEQ
INNER JOIN (SELECT SEQ , MAX(DTL_SEQ) DTL_SEQ FROM CRM_CUST_MAINTENANCE_HIST GROUP BY SEQ) B ON A.SEQ = B.SEQ INNER JOIN CRM_CUST_MAINTENANCE_HIST C ON A.SEQ = C.SEQ AND B.DTL_SEQ = C.DTL_SEQ
INNER JOIN CRM_CUST_OPERATE_INFO D ON A.SEQ = D.SEQ WHERE 1 = 1
AND C.BILL_CODE = #{search_type1, jdbcType=VARCHAR}
AND D.DEAL_CODE = #{search_type2, jdbcType=VARCHAR}
AND C.MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE , -1), 'YYYYMMDD')
AND C.MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE , -2), 'YYYYMMDD')
AND C.MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE , -3), 'YYYYMMDD')
AND C.CONTRACT_DT >= #{start_date, jdbcType=VARCHAR}
AND C.CONTRACT_DT <= #{end_date, jdbcType=VARCHAR}
AND REGEXP_REPLACE(C.MON_OFF_AMT, ',', '') >= #{search_text, jdbcType=VARCHAR}
AND REGEXP_REPLACE(C.MON_OFF_AMT, ',', '') <= #{search_text2, jdbcType=VARCHAR}
AND UPPER(A.CUST_KOR_NAME) LIKE '%'|| UPPER(#{search_type3, jdbcType=VARCHAR}) ||'%'
) IN_TB
WHERE RECEIVE_AMT > 0
